21	// Client is an authenticated HTTP client for the Entire API.
22	// It attaches the bearer token to all outgoing requests via the Authorization header.
23	type Client struct {
24		httpClient *http.Client
25		baseURL    string
26	
27		// trailBackend is "legacy" for the BFF or "entire-api" for the cell API.
28		// Empty keeps the generic client's historical behavior and is treated as
29		// legacy by CLI selection code only.
30		trailBackend string
31		trailRoutes  map[string]string
32	
33		// authSessionsPath is the base path for entire-core's login-session
34		// endpoints (list / revoke / current). Set via WithAuthSessionsPath when the
35		// client targets the auth host; empty otherwise, and the session methods
36		// error out if called against an empty path.
37		authSessionsPath string
38	}
39	
40	// WithAuthSessionsPath sets the base path used by ListAuthSessions,
41	// RevokeCurrentAuthSession, and RevokeAuthSession. Returns the receiver for chaining
42	// at construction:
43	//
44	//	c := api.NewClientWithBaseURL(token, base).WithAuthSessionsPath(p)
45	func (c *Client) WithAuthSessionsPath(path string) *Client {
46		c.authSessionsPath = path
47		return c
48	}
49	
50	// NewClient creates a new authenticated API client with an explicit bearer
51	// token, targeting the data API base URL (BaseURL()).
52	func NewClient(token string) *Client {
53		return NewClientWithBaseURL(token, BaseURL())
54	}
55	
56	// NewClientWithBaseURL creates a new authenticated API client targeting an
57	// explicit base URL. Use this for endpoints that live on a login server
58	// rather than the data API (e.g. auth-session management).
59	func NewClientWithBaseURL(token, baseURL string) *Client {
60		return &Client{
61			httpClient: &http.Client{
62				Transport: &bearerTransport{
63					token: token,
64					base:  http.DefaultTransport,
65				},
66				// A cross-host redirect must never carry the Entire bearer to
67				// another origin; refuse it rather than follow it. Same-origin
68				// requests are guaranteed by the base-host check in do().
69				CheckRedirect: rejectCrossHostRedirect,
70			},
71			baseURL: baseURL,
72		}
73	}
74	
75	// rejectCrossHostRedirect stops a redirect chain from leaving the origin the
76	// client was built for. Same-host redirects (e.g. a trailing-slash normalize)
77	// still follow, up to Go's usual 10-hop cap.
78	func rejectCrossHostRedirect(req *http.Request, via []*http.Request) error {
79		if len(via) >= 10 {
80			return errors.New("stopped after 10 redirects")
81		}
82		if len(via) > 0 && !strings.EqualFold(req.URL.Host, via[0].URL.Host) {
83			return fmt.Errorf("refusing redirect to a different host (%s → %s): the Entire bearer must not leave its origin", via[0].URL.Host, req.URL.Host)
84		}
85		return nil
86	}
87	
88	// requireSameHost rejects an endpoint whose host differs from the base URL's.
89	// It guards the direct case (a path that resolved to another host); redirects
90	// are handled by rejectCrossHostRedirect.
91	func requireSameHost(baseURL, endpoint string) error {
92		b, err := url.Parse(baseURL)
93		if err != nil {
94			return fmt.Errorf("parse base URL: %w", err)
95		}
96		e, err := url.Parse(endpoint)
97		if err != nil {
98			return fmt.Errorf("parse endpoint URL: %w", err)
99		}
100		if !strings.EqualFold(b.Host, e.Host) {
101			return fmt.Errorf("refusing to send an authenticated request to %q, which is not the API host %q", e.Host, b.Host)
102		}
103		return nil
104	}
105	
106	// bearerTransport is an http.RoundTripper that injects the Authorization header.
107	//
108	// The token is only ever sent to the client's base host: do() rejects a request
109	// URL whose host differs from the base, and CheckRedirect refuses a cross-host
110	// redirect, so every request this transport sees is same-origin as the base.
111	//
112	// When token is empty, the Authorization header is omitted (rather than sent
113	// as a malformed "Authorization: Bearer "). This supports endpoints like
114	// recap that deliberately want the unauthenticated request to reach the
115	// server so it can return a typed 401 — callers that want a local fast-fail
116	// for missing auth should check ErrNotLoggedIn at construction time, not
117	// rely on the transport.
118	type bearerTransport struct {
119		token string
120		base  http.RoundTripper
121	}
122	
123	func (t *bearerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
124		// Clone the request to avoid mutating the caller's request.
125		r := req.Clone(req.Context())
126		if t.token != "" {
127			r.Header.Set("Authorization", "Bearer "+t.token)
128		}
129		r.Header.Set("User-Agent", versioninfo.UserAgent())
130		if r.Header.Get("Accept") == "" {
131			r.Header.Set("Accept", "application/json")
132		}
133		resp, err := t.base.RoundTrip(r)
134		if err != nil {
135			return nil, fmt.Errorf("round trip: %w", err)
136		}
137		return resp, nil
138	}
