140	// Get sends an authenticated GET request to the given API-relative path.
141	func (c *Client) Get(ctx context.Context, path string) (*http.Response, error) {
142		return c.do(ctx, http.MethodGet, path, nil, nil)
143	}
144	
145	// GetStream sends an authenticated GET request with optional extra request
146	// headers (e.g. Accept: text/event-stream, Last-Event-ID) and returns the
147	// response with the body still open. Callers are responsible for reading and
148	// closing resp.Body. Intended for streaming endpoints such as Server-Sent
149	// Events; for normal JSON requests use Get.
150	func (c *Client) GetStream(ctx context.Context, path string, headers http.Header) (*http.Response, error) {
151		return c.do(ctx, http.MethodGet, path, nil, headers)
152	}
