154	// doJSON sends an authenticated request with an optional JSON-marshaled body.
155	func (c *Client) doJSON(ctx context.Context, method, path string, body any) (*http.Response, error) {
156		var reader io.Reader
157		if body != nil {
158			if c.trailBackend == "legacy" {
159				var err error
160				body, err = legacyTrailRequestBody(body)
