164			}
165			data, err := json.Marshal(body)
166			if err != nil {
167				return nil, fmt.Errorf("marshal request body: %w", err)
168			}
169			reader = bytes.NewReader(data)
170		}
171		return c.do(ctx, method, path, reader, nil)
172	}
