179	// Put sends an authenticated PUT request with a JSON body to the given API-relative path.
180	func (c *Client) Put(ctx context.Context, path string, body any) (*http.Response, error) {
181		return c.doJSON(ctx, http.MethodPut, path, body)
182	}
183	
184	// Patch sends an authenticated PATCH request with a JSON body to the given API-relative path.
185	func (c *Client) Patch(ctx context.Context, path string, body any) (*http.Response, error) {
186		return c.doJSON(ctx, http.MethodPatch, path, body)
187	}
