189	// Delete sends an authenticated DELETE request to the given API-relative path.
190	func (c *Client) Delete(ctx context.Context, path string) (*http.Response, error) {
191		return c.do(ctx, http.MethodDelete, path, nil, nil)
192	}
193	
194	// Request sends an authenticated request with an explicit method, optional
195	// extra headers, and an optional raw body. It's the general-purpose escape
196	// hatch behind `entire api`; prefer the typed verbs (Get/Post/…) for normal
197	// use. The bearer, User-Agent, and default Accept are still attached by the
198	// transport; a body defaults to Content-Type: application/json unless the
199	// caller supplies its own via headers.
200	func (c *Client) Request(ctx context.Context, method, path string, headers http.Header, body io.Reader) (*http.Response, error) {
201		return c.do(ctx, method, path, body, headers)
202	}
