213	// SetTrailRoute registers the entire-api base path for a resolved trail. The
214	// legacy BFF already uses trail-ID routes, so registration is a no-op there.
215	func (c *Client) SetTrailRoute(trailID, path string) {
216		if c.trailBackend != "entire-api" {
217			return
218		}
219		trailID = strings.TrimSpace(trailID)
220		path = strings.TrimRight(strings.TrimSpace(path), "/")
221		if trailID == "" || path == "" {
222			return
223		}
224		if c.trailRoutes == nil {
225			c.trailRoutes = make(map[string]string)
226		}
227		c.trailRoutes[url.PathEscape(trailID)] = path
228	}
229	
230	func (c *Client) rewriteTrailRoute(path string) string {
231		const prefix = "/api/v1/trails/"
232		if !strings.HasPrefix(path, prefix) || len(c.trailRoutes) == 0 {
233			return path
234		}
235		rest := strings.TrimPrefix(path, prefix)
236		id, suffix, _ := strings.Cut(rest, "/")
237		base, ok := c.trailRoutes[id]
238		if !ok {
239			return path
240		}
241		if suffix == "" {
242			return base
243		}
244		return base + "/" + suffix
245	}
246	
247	func (c *Client) do(ctx context.Context, method, path string, body io.Reader, headers http.Header) (*http.Response, error) {
248		path = c.rewriteTrailRoute(path)
249		endpoint, err := ResolveURLFromBase(c.baseURL, path)
250		if err != nil {
251			return nil, fmt.Errorf("resolve URL %s: %w", path, err)
252		}
253		// The bearer is only ever sent to the API's own host. A path that resolves
254		// to another host (absolute or scheme-relative URL) would otherwise redirect
255		// the Authorization header off-origin.
256		if err := requireSameHost(c.baseURL, endpoint); err != nil {
257			return nil, err
258		}
259	
260		req, err := http.NewRequestWithContext(ctx, method, endpoint, body)
261		if err != nil {
262			return nil, fmt.Errorf("create request: %w", err)
263		}
264	
265		for k, vs := range headers {
266			for _, v := range vs {
267				req.Header.Add(k, v)
268			}
269		}
270	
271		// Default a body's Content-Type to JSON, but don't clobber a caller-supplied
272		// one — the `entire api -H 'Content-Type: …'` escape hatch must be able to
273		// send non-JSON bodies.
274		if body != nil && req.Header.Get("Content-Type") == "" {
275			req.Header.Set("Content-Type", "application/json")
276		}
277	
278		resp, err := c.httpClient.Do(req)
279		if err != nil {
280			return nil, fmt.Errorf("%s %s: %w", method, path, err)
281		}
282		return resp, nil
283	}
