285	// DecodeJSON reads the response body and decodes it into dest.
286	// It limits the body size to protect against unbounded reads.
287	// The caller is responsible for closing resp.Body.
288	func DecodeJSON(resp *http.Response, dest any) error {
289		body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
290		if err != nil {
291			return fmt.Errorf("read response body: %w", err)
292		}
293	
294		if err := json.Unmarshal(body, dest); err != nil {
295			return fmt.Errorf("decode JSON response: %w", err)
296		}
297	
298		return nil
299	}
