301	// ErrorResponse represents a standard API error response. Older endpoints
302	// return {"error":"message"}; newer endpoints return
303	// {"error":{"code":"...","message":"...",...}}.
304	type ErrorResponse struct {
305		Error any `json:"error"`
306	}
307	
308	// Message extracts the human-readable error message from either envelope shape.
309	func (e ErrorResponse) Message() string {
310		switch v := e.Error.(type) {
311		case string:
312			return strings.TrimSpace(v)
313		case map[string]any:
314			if message, ok := v["message"].(string); ok && strings.TrimSpace(message) != "" {
315				return strings.TrimSpace(message)
316			}
317			if code, ok := v["code"].(string); ok && strings.TrimSpace(code) != "" {
318				return strings.TrimSpace(code)
319			}
320		}
321		return ""
322	}
323	
324	// HTTPError is returned by CheckResponse for non-2xx responses. Callers can use
325	// errors.As to inspect the HTTP status, or IsHTTPErrorStatus for a quick check.
326	type HTTPError struct {
327		StatusCode int
328		Message    string
329	}
330	
331	func (e *HTTPError) Error() string {
332		if e.Message != "" {
333			return fmt.Sprintf("API error: %s (status %d)", e.Message, e.StatusCode)
334		}
335		return fmt.Sprintf("API error: status %d", e.StatusCode)
336	}
337	
338	// IsHTTPErrorStatus reports whether err wraps an *HTTPError with the given HTTP status.
339	func IsHTTPErrorStatus(err error, status int) bool {
340		var ae *HTTPError
341		return errors.As(err, &ae) && ae.StatusCode == status
342	}
343	
344	// CheckResponse returns an error if the response status code indicates failure.
345	// For non-2xx responses, it reads and parses the error message from the body
346	// and returns it as an *HTTPError. The caller is responsible for closing resp.Body.
347	func CheckResponse(resp *http.Response) error {
348		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
349			return nil
350		}
351	
352		apiError := &HTTPError{StatusCode: resp.StatusCode}
353	
354		body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
355		if err != nil {
356			return apiError
357		}
358	
359		var parsed ErrorResponse
360		if err := json.Unmarshal(body, &parsed); err == nil {
361			if message := parsed.Message(); message != "" {
362				apiError.Message = message
363				return apiError
364			}
365		}
366	
367		if text := strings.TrimSpace(string(body)); text != "" {
368			apiError.Message = text
369		}
370		return apiError
371	}
