52	func snakeCaseTrailJSONValue(value any, typ reflect.Type) any {
53		typ = indirectTrailJSONType(typ)
54		if typ == nil || typ == rawJSONType {
55			return value
56		}
57		switch v := value.(type) {
58		case map[string]any:
59			if typ.Kind() != reflect.Struct {
60				return value
61			}
62			out := make(map[string]any, len(v))
63			for key, child := range v {
64				fieldType, canonical, ok := trailJSONStructField(typ, key)
65				if !ok {
66					out[key] = child
67					continue
68				}
69				out[lowerCamelToSnake(canonical)] = snakeCaseTrailJSONValue(child, fieldType)
70			}
71			return out
72		case []any:
73			if typ.Kind() != reflect.Slice && typ.Kind() != reflect.Array {
74				return value
75			}
76			for i := range v {
77				v[i] = snakeCaseTrailJSONValue(v[i], typ.Elem())
78			}
79		}
80		return value
81	}
82	
83	func lowerCamelToSnake(value string) string {
84		var out strings.Builder
85		for i, r := range value {
86			if unicode.IsUpper(r) {
87				if i > 0 {
88					out.WriteByte('_')
89				}
90				r = unicode.ToLower(r)
91			}
92			out.WriteRune(r)
93		}
94		return out.String()
95	}
