97	func normalizeTrailJSONValue(value any, typ reflect.Type) any {
98		typ = indirectTrailJSONType(typ)
99		if typ == nil || typ == rawJSONType {
100			return value
101		}
102		switch v := value.(type) {
103		case map[string]any:
104			if typ.Kind() != reflect.Struct {
105				return value
106			}
107			out := make(map[string]any, len(v))
108			for key, child := range v {
109				fieldType, canonical, ok := trailJSONStructField(typ, NormalizeTrailJSONKey(key))
110				if !ok {
111					// Unknown fields are ignored by encoding/json. Preserve their entire
112					// subtree so a future free-form field cannot be silently re-cased.
113					out[key] = child
114					continue
115				}
116				out[canonical] = normalizeTrailJSONValue(child, fieldType)
117			}
118			return out
119		case []any:
120			if typ.Kind() != reflect.Slice && typ.Kind() != reflect.Array {
121				return value
122			}
123			for i := range v {
124				v[i] = normalizeTrailJSONValue(v[i], typ.Elem())
125			}
126		}
127		return value
128	}
129	
130	func indirectTrailJSONType(typ reflect.Type) reflect.Type {
131		for typ != nil && typ.Kind() == reflect.Pointer {
132			typ = typ.Elem()
133		}
134		return typ
135	}
136	
137	func trailJSONStructField(typ reflect.Type, key string) (reflect.Type, string, bool) {
138		for i := range typ.NumField() {
139			field := typ.Field(i)
140			name := strings.Split(field.Tag.Get("json"), ",")[0]
141			if name == "" {
142				name = field.Name
143			}
144			if name == "-" || name != key {
145				continue
146			}
147			return field.Type, name, true
148		}
149		return nil, "", false
150	}
