152	// NormalizeTrailJSONKey converts a legacy trail key to its canonical entire-api
153	// spelling. Event and response normalization share this helper so aliases do
154	// not diverge between SSE and regular JSON decoding.
155	func NormalizeTrailJSONKey(value string) string {
156		camel := snakeToLowerCamel(value)
157		if camel == "reviewSessionId" {
158			return "reviewId"
159		}
160		return camel
161	}
162	
163	func snakeToLowerCamel(value string) string {
164		if !strings.ContainsRune(value, '_') {
165			return value
166		}
167		var out strings.Builder
168		upperNext := false
169		for _, r := range value {
170			if r == '_' {
171				upperNext = true
172				continue
173			}
174			if upperNext {
175				r = unicode.ToUpper(r)
176				upperNext = false
177			}
178			out.WriteRune(r)
179		}
180		return out.String()
181	}
