574	func listTrailResources(ctx context.Context, client *api.Client, forge, owner, repo string, statuses []trail.Status, author string, limit int) ([]api.TrailResource, int, error) {
575		if limit <= 0 {
576			return nil, 0, errors.New("limit must be greater than 0")
577		}
578		if !isEntireAPITrailClient(client) {
579			return listLegacyTrailResources(ctx, client, forge, owner, repo, statuses, author, limit)
580		}
581		items := make([]api.TrailResource, 0, min(limit, trailListServerMaxLimit))
582		pageToken := ""
583		seenTokens := map[string]bool{}
584		totalMatched := 0
585		for {
586			pageSize := trailListServerMaxLimit
587			if author == "" && limit-len(items) < pageSize {
588				pageSize = limit - len(items)
589			}
590			resp, err := client.Get(ctx, trailsBasePath(forge, owner, repo)+trailListPageQuery(statuses, pageSize, pageToken))
591			if err != nil {
592				return nil, 0, fmt.Errorf("failed to list trails: %w", err)
593			}
594			var page api.TrailListResponse
595			decodeErr := func() error {
596				defer resp.Body.Close()
597				if err := checkTrailResponse(resp); err != nil {
598					return err
599				}
600				if err := api.DecodeJSON(resp, &page); err != nil {
601					return fmt.Errorf("failed to decode trail list: %w", err)
602				}
603				return nil
604			}()
605			if decodeErr != nil {
606				return nil, 0, decodeErr
607			}
608	
609			for _, resource := range page.Trails {
610				if author != "" {
611					login := ""
612					if resource.Author != nil && resource.Author.Login != nil {
613						login = *resource.Author.Login
614					}
615					if !strings.EqualFold(login, author) {
616						continue
617					}
618				}
619				totalMatched++
620				if len(items) < limit {
621					items = append(items, resource)
622				}
623				if author != "" && len(items) >= limit {
624					break
625				}
626			}
627			// entire-api's author filter accepts account IDs while the CLI accepts
628			// logins, so this path filters locally. Stop as soon as --limit is
629			// satisfied rather than walking the repository's complete trail history.
630			if author != "" && len(items) >= limit {
631				break
632			}
633			if author == "" {
634				totalMatched = page.Total
635				if totalMatched < len(items) {
636					totalMatched = len(items)
637				}
638				if len(items) >= limit {
639					break
640				}
641			}
642			if page.NextPageToken == nil || strings.TrimSpace(*page.NextPageToken) == "" {
643				break
644			}
645			pageToken = strings.TrimSpace(*page.NextPageToken)
646			if seenTokens[pageToken] {
647				return nil, 0, fmt.Errorf("trail list pagination repeated page token %q", pageToken)
648			}
649			seenTokens[pageToken] = true
650		}
651		return items, totalMatched, nil
652	}
