675	// statuses (--status any) omit the filter. Author is intentionally absent: the
676	// CLI accepts a login while this API's author filter accepts account ULIDs.
677	func trailListPageQuery(statusFilters []trail.Status, pageSize int, pageToken string) string {
678		q := url.Values{}
679		if len(statusFilters) > 0 {
680			parts := make([]string, len(statusFilters))
681			for i, status := range statusFilters {
682				parts[i] = string(status)
683			}
684			q.Set("status", strings.Join(parts, ","))
685		}
686		if pageSize <= 0 || pageSize > trailListServerMaxLimit {
687			pageSize = trailListServerMaxLimit
688		}
689		q.Set("pageSize", strconv.Itoa(pageSize))
690		if strings.TrimSpace(pageToken) != "" {
691			q.Set("pageToken", strings.TrimSpace(pageToken))
692		}
693		return "?" + q.Encode()
694	}
